package org.strongswan.android.rookstride;
import org.json.*;import org.junit.Test;import java.net.URL;import java.nio.charset.StandardCharsets;import static org.junit.Assert.*;
public final class PublicArtifactCatalogTest {
    static final byte[] BYTES="public archive fixture".getBytes(StandardCharsets.UTF_8);
    static JSONObject document(byte[] data)throws Exception{
        JSONObject artifacts=new JSONObject();
        for(String id:new String[]{"adguard","xray","trusttunnel"}){String version=id.equals("adguard")?"v0.107.80":id.equals("xray")?"v26.3.27":"v1.1.0";JSONObject assets=new JSONObject();for(String arch:new String[]{"x86_64","aarch64"}){String repo=id.equals("adguard")?"AdguardTeam/AdGuardHome":id.equals("xray")?"XTLS/Xray-core":"TrustTunnel/TrustTunnel";JSONArray sources=new JSONArray().put(new JSONObject().put("url","https://github.com/"+repo+"/releases/download/"+version+"/fixture-"+arch).put("headers",new JSONObject()));if(id.equals("adguard"))sources.put(new JSONObject().put("url","https://api.github.com/repos/AdguardTeam/AdGuardHome/releases/assets/705629752").put("headers",new JSONObject().put("Accept","application/octet-stream")));assets.put(arch,new JSONObject().put("bytes",data.length).put("sha256",PublicArtifactCatalog.hash(data)).put("sources",sources));}artifacts.put(id,new JSONObject().put("version",version).put("assets",assets));}
        return new JSONObject().put("schema",1).put("redirect_hosts",new JSONArray().put("github.com").put("api.github.com").put("release-assets.githubusercontent.com")).put("artifacts",artifacts);
    }
    static PublicArtifactCatalog catalog()throws Exception{return new PublicArtifactCatalog(document(BYTES).toString().getBytes(StandardCharsets.UTF_8));}
    private interface Checked{void run()throws Exception;}
    private static void refuses(Checked action)throws Exception{try{action.run();fail("Invalid public metadata was accepted");}catch(java.io.IOException expected){}}
    @Test public void rawApkCatalogBytesBindBothArchitecturesAndPublicOrigins()throws Exception{JSONObject d=document(BYTES);byte[] raw=d.toString().getBytes(StandardCharsets.UTF_8);PublicArtifactCatalog c=new PublicArtifactCatalog(raw);assertEquals(PublicArtifactCatalog.hash(raw),c.sha256);for(String arch:new String[]{"x86_64","aarch64"})for(String id:new String[]{"adguard","xray","trusttunnel"})assertEquals(BYTES.length,c.asset(id,arch).bytes);}
    @Test public void unknownIdsArchitecturesAndRemoteAuthorityAreRejected()throws Exception{PublicArtifactCatalog c=catalog();refuses(()->c.asset("trojan","x86_64"));refuses(()->c.asset("adguard","armv7"));for(String url:new String[]{"http://github.com/x","https://evil.example/x","https://github.com:444/x","https://user@github.com/x","https://github.com/x#fragment"})refuses(()->c.validateUrl(new URL(url)));}
    @Test public void headersOversizedAssetsAndUntrustedSourcesCannotEnterCatalog()throws Exception{JSONObject d=document(BYTES);JSONObject a=d.getJSONObject("artifacts").getJSONObject("adguard").getJSONObject("assets").getJSONObject("x86_64");a.put("bytes",PublicArtifactCatalog.MAX_ARCHIVE_BYTES+1);refuses(()->new PublicArtifactCatalog(d.toString().getBytes(StandardCharsets.UTF_8)));a.put("bytes",BYTES.length);a.getJSONArray("sources").getJSONObject(0).getJSONObject("headers").put("Authorization","secret");refuses(()->new PublicArtifactCatalog(d.toString().getBytes(StandardCharsets.UTF_8)));}
    @Test public void malformedUtf8AndCatalogExtensionAreNotSilentlyAccepted()throws Exception{refuses(()->new PublicArtifactCatalog(new byte[]{(byte)0xc3,(byte)0x28}));JSONObject d=document(BYTES).put("server_url","https://evil.example");refuses(()->new PublicArtifactCatalog(d.toString().getBytes(StandardCharsets.UTF_8)));}
}
